import style from "./index.css?raw";

class CollapsibleSelect extends HTMLElement {
    static get observedAttributes() {
        return ['placeholder'];
    }
    constructor() {
        super();
        this.attachShadow({ mode: "open" });
        this.icon = `<svg t="1721814180387"  viewBox="0 0 1024 1024" version="1.1" xmlns="http://www.w3.org/2000/svg" p-id="1939" width="16" height="16"><path d="M818.07039273 512L329.94971923 23.87932647l-111.86098796 101.69180708L604.51759771 512 218.08873127 898.42886645 329.94971923 1010.28985441z" fill="#666" p-id="1940"></path></svg>`
        this.shadowRoot.innerHTML = `
            <style> ${style} </style>
            <div class="select-box">
                <div class="selected">
                    ${this.icon}
                    <span class="placeholder">${this.placeholder}</span>
                </div>
                <div class="dropdown"></div>
            </div>
        `;
        this.data = [];
        this.selectedValue = "";
    }
    connectedCallback() {
        this.shadowRoot.querySelector('.selected span').textContent = this.placeholder;
        this.render();
        this.shadowRoot.querySelector(".selected").onclick = () => {
            this.shadowRoot.querySelector(".select-box").classList.toggle("open");
        };
        document.addEventListener("click", this._closeOnOutside);
    }
    disconnectedCallback() {
        document.removeEventListener("click", this._closeOnOutside);
    }
    set options(data) {
        this.data = JSON.parse(data);
        this.render();
    }
    get placeholder() {
        return this.getAttribute('placeholder') || ''
    }

    clearValue() {
        this.selectedValue = ''
        this.shadowRoot.querySelector('.selected span').textContent = this.placeholder;
        this.shadowRoot.querySelector('.selected span').classList.add('placeholder')
        this.render()
    }

    render() {
        const dropdown = this.shadowRoot.querySelector(".dropdown");
        dropdown.innerHTML = "";
        if (!this.data) return
        let html = ''
        this.data.forEach((group) => {
            html += `
                <div>
                    <div class="group">
                        ${this.icon}
                        <span>${group.label}</span>
                    </div>
                    <div class="options">
                        ${group.options.map((opt) => `
                            <div class="option ${opt.value === this.selectedValue ? 'option-selected' : ''} " data-value="${opt.value}">
                                ${opt.label}
                            </div>
                        `).join("")}
                    </div>
                </div>
            `
        });
        dropdown.innerHTML = html;
        // 监听分组点击事件
        dropdown.querySelectorAll('.group').forEach(group => {
            group.onclick = () => {
                group.parentNode.classList.toggle('collapsed');
            }
        });
        // 监听选项点击事件
        dropdown.querySelectorAll('.option').forEach(option => {
            const isSelect = option.dataset.is_select || 'false'
            if (isSelect == 'true') {
                return
            }
            option.onclick = (e) => {
                e.stopPropagation();
                const optValue = this.data.reduce((acc, group) => {
                    const opt = group.options.find(o => o.value == option.dataset.value);
                    return opt ? opt.value : acc;
                }, '');
                this.selectedValue = optValue;
                this.shadowRoot.querySelector('.selected span').textContent = option.textContent.trim();
                this.shadowRoot.querySelector('.selected span').classList.remove('placeholder')
                this.shadowRoot.querySelector('.select-box').classList.remove('open');
                this.render();
                this.dispatchEvent(new CustomEvent('change', { detail: optValue, bubbles: true, composed: true }));
            };
        });
    }
    _closeOnOutside = (e) => {
        if (!this.contains(e.target) && !this.shadowRoot.contains(e.target)) {
            this.shadowRoot.querySelector(".select-box").classList.remove("open");
        }
    };
}
if (!customElements.get("collapsible-select")) {
    customElements.define("collapsible-select", CollapsibleSelect);
}
